sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below

   // Replace with your reference field name

 var refValue = g_form.getValue('x_cdltd_asset_prof_asset_profile_request'); 
    if (!refValue) {
        g_form.setValue('user_field', ''); // Clear if no reference
        return;
    }



   var ga = new GlideAjax('GetUserFromReference');
    ga.addParam('sysparm_name', 'getUser');
    ga.addParam('sysparm_ref_sys_id', refValue);
    ga.getXMLAnswer(function(response) {
        if (response) {
            g_form.setValue('information_security_offficer_iso', response); // Set the user field
        }
    });



}
